const api=(window.API_BASE_URL||'').replace(/\/$/,'');
const $=s=>document.querySelector(s),t=s=>I18N.t(s);
let connected=false,chosen=null,raceEvents=RACE_EVENTS,activeFilter='all',healthReady=false,healthStates={},loadError=false;
const eventImage=(url,type='road')=>url?.startsWith('/uploads/')?api+url:url?.startsWith('assets/')?url:({trail:'assets/community-1.jpg',family:'assets/community-2.jpg',road:'assets/community-1.jpg'}[type]||'assets/community-1.jpg');
const escapeHTML=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt=s=>new Intl.DateTimeFormat(I18N.lang,{day:'numeric',month:'long',year:'numeric',timeZone:'Asia/Jerusalem'}).format(new Date(s));
function modeNotice(){ $('#modeNotice').textContent=t(loadError?'تعذّر تحميل السباقات. حدّث الصفحة وحاول مجددًا.':!connected?'معاينة فقط؛ شغّل الخادم لحفظ التسجيلات وعرضها للأدمن.':healthReady?'التسجيل متاح وخدمات التذكير مهيأة.':'التسجيل متاح؛ إرسال التذكير ينتظر إعداد خدمات واتساب والبريد.'); }
function render(filter=activeFilter){window.BatoufContent?.home(raceEvents.find(e=>e.id==='arraba-2026'));activeFilter=filter;const list=raceEvents.filter(e=>filter==='all'||e.type===filter);$('#empty').hidden=!!list.length;$('#eventGrid').innerHTML=list.map(raw=>{const e=I18N.event(raw);return `<article class="card"><div class="card-art"><img src="${escapeHTML(eventImage(e.images?.[0]?.url,e.type))}" alt="${escapeHTML(e.images?.length?e.name:t('عدّاؤون في سباق — صورة توضيحية'))}" loading="lazy"><span class="badge">${escapeHTML(e.label)}</span><div class="distance-art">${escapeHTML(e.art)}<small>${e.eventDate?'2026':I18N.lang==='ar'?'كيلومترات':I18N.lang==='he'?'קילומטרים':'KILOMETERS'}</small></div></div><div class="card-body"><span class="date">${fmt(e.start)}</span><h3>${escapeHTML(e.name)}</h3><p class="location">${escapeHTML(e.location)}</p><div class="chips">${e.distances.map(d=>`<span>${escapeHTML(I18N.distance(d))}</span>`).join('')}</div><div class="card-bottom"><span>${t(e.sample!==false?'سباق نموذجي':'التسجيل متاح')}</span><a href="#batoufHome">${t('برنامج اليوم')}</a></div></div></article>`}).join('')}
function renderDetails(){if(!chosen)return;window.StudentForm?.apply($('#registrationForm'),chosen);const e=I18N.event(chosen),select=$('#registrationForm select[name=distance]'),distance=select?.value;$('#details').innerHTML=`${e.images?.length?`<div class="event-photo-gallery"><img id="eventCover" src="${escapeHTML(eventImage(e.images[0].url))}" alt="${escapeHTML(e.name)}"><div>${e.images.map((image,i)=>`<button type="button" data-gallery-image="${i}" aria-label="${escapeHTML(t('صورة'))} ${i+1}"><img src="${escapeHTML(eventImage(image.url))}" alt=""></button>`).join('')}</div></div>`:''}<p class="eyebrow">${escapeHTML(e.label)}</p><h2>${escapeHTML(e.name)}</h2><p>${fmt(e.start)} · ${e.timePending?t('ساعة الانطلاق تُعلن لاحقًا'):new Date(e.start).toLocaleTimeString(I18N.lang,{hour:'2-digit',minute:'2-digit',timeZone:'Asia/Jerusalem'})}</p><p>${escapeHTML(e.location)}</p><p class="batouf-description">${escapeHTML(e.description)}</p>${e.id==='arraba-2026'&&document.querySelector('[data-registration-page]')?BatoufContent.sponsors(e):''}`;if(select){select.innerHTML=chosen.distances.map(d=>`<option value="${escapeHTML(d)}">${escapeHTML(I18N.distance(d))}</option>`).join('');if(chosen.distances.includes(distance))select.value=distance;}}
render();
initializeRegistrationPage();
document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));render(b.dataset.filter)}));
$('#eventGrid').addEventListener('click',e=>{const b=e.target.closest('[data-event]');if(!b)return;chosen=raceEvents.find(x=>x.id===b.dataset.event);$('#registrationForm').reset();$('#formStatus').textContent='';renderDetails();if($('#eventDialog').showModal)$('#eventDialog').showModal();else $('#eventDialog').scrollIntoView({block:'start'})});
document.querySelectorAll('dialog .close').forEach(b=>b.addEventListener('click',()=>b.closest('dialog').close()));
$('#registrationForm').addEventListener('submit',async e=>{e.preventDefault();const form=e.target,status=$('#formStatus');status.className='';if(!connected){status.textContent=t('النموذج جاهز. هذه معاينة فقط؛ شغّل الخادم المرفق لحفظ التسجيل في قاعدة البيانات. لم تُحفظ أو تُرسل بياناتك.');return}const fd=new FormData(form);if(chosen.registrationProfile!=='student'&&!fd.has('emailConsent')&&!fd.has('whatsappConsent')){status.className='error';status.textContent=t('اختر قناة واحدة على الأقل لاستلام التذكير.');return}$('#submitBtn').disabled=true;try{const r=await fetch(api+'/api/registrations',{method:'POST',headers:{'Content-Type':'application/json','Accept-Language':I18N.lang},body:JSON.stringify({...(chosen.registrationProfile==='student'?StudentForm.payload(fd):{}),eventId:chosen.id,name:fd.get('name'),email:fd.get('email'),phone:fd.get('phone'),distance:chosen.id==='arraba-2026'?chosen.distances[0]:fd.get('distance'),age:fd.get('age'),emailConsent:fd.has('emailConsent'),whatsappConsent:fd.has('whatsappConsent'),language:I18N.lang})});const d=await r.json();if(!r.ok)throw Error(d.error||t('تعذّر إكمال التسجيل'));status.className='success';status.textContent=t(d.message);const success=document.querySelector('#registrationSuccess');if(success){success.hidden=false;success.innerHTML=`<a class="btn" href="participant.html#token=${escapeHTML(d.participantToken)}">${t('صفحتي وبطاقة المشاركة')}</a><strong class="registration-number">${t('رقم التسجيل')}: #${d.bib}</strong><p>${t('احتفظ بهذا الرابط؛ هو خاص بمشاركتك.')}</p>`}form.reset()}catch(err){status.className='error';status.textContent=t(err.message||'تعذّر الاتصال. حاول لاحقًا.')}finally{$('#submitBtn').disabled=false}});
fetch(api+'/api/health',{headers:{'Accept-Language':I18N.lang}}).then(async r=>{if(!r.ok)return;const d=await r.json();if(d.app!=='khotwa')return;connected=true;healthStates=d.messagingByLanguage||{};healthReady=healthStates[I18N.lang]??d.messagingReady;modeNotice();fetch(api+'/api/events').then(async r=>{if(!r.ok)throw Error();raceEvents=await r.json();render();initializeRegistrationPage()}).catch(()=>{loadError=true;modeNotice()})}).catch(()=>{});
window.addEventListener('languagechange',()=>{healthReady=healthStates[I18N.lang]??false;render();initializeRegistrationPage();renderDetails();modeNotice();$('#formStatus').textContent=''});
setTimeout(()=>document.querySelector('.logo-intro')?.remove(),1500);

function initializeRegistrationPage(){const picker=document.querySelector('#racePicker');if(!picker)return;const previous=picker.dataset.userSelected==='true'?chosen?.id:(new URLSearchParams(location.search).get('event')||chosen?.id);picker.innerHTML=raceEvents.map(e=>`<option value="${escapeHTML(e.id)}">${escapeHTML(I18N.event(e).name)} · ${fmt(e.start)}</option>`).join('');chosen=raceEvents.find(e=>e.id===previous)||raceEvents[0];if(!chosen){document.querySelector('#registrationForm').hidden=true;return}document.querySelector('#registrationForm').hidden=false;picker.value=chosen.id;renderDetails();picker.onchange=()=>{picker.dataset.userSelected='true';chosen=raceEvents.find(e=>e.id===picker.value);renderDetails();document.querySelector('#formStatus').textContent=''}}

document.querySelector('#details').addEventListener('click',e=>{const b=e.target.closest('[data-gallery-image]');if(!b||!chosen)return;const image=chosen.images?.[Number(b.dataset.galleryImage)];if(image)document.querySelector('#eventCover').src=eventImage(image.url)});

window.addEventListener('studentformtranslated',renderDetails);
